--
-- Name: v_blocked_slots_upcoming; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_blocked_slots_upcoming WITH (security_invoker='true') AS
 SELECT id,
    doctor_name,
    branch,
    start_date,
    end_date,
    start_time,
    end_time,
    reason,
    description,
    created_at,
    created_by,
    updated_at,
        CASE
            WHEN (start_date > CURRENT_DATE) THEN 'futuro'::text
            WHEN (end_date < CURRENT_DATE) THEN 'passado'::text
            ELSE 'atual'::text
        END AS status_temporal
   FROM public.blocked_slots bs
  WHERE (end_date >= (CURRENT_DATE - '30 days'::interval))
  ORDER BY start_date;


ALTER VIEW public.v_blocked_slots_upcoming OWNER TO postgres;

