    CONSTRAINT waiting_list_priority_criteria_check CHECK ((priority_criteria = ANY (ARRAY['arrival'::text, 'urgency'::text, 'coverage'::text, 'seniority'::text]))),
    CONSTRAINT waiting_list_status_check CHECK ((status = ANY (ARRAY['aguardando'::text, 'notificado'::text, 'alocado'::text, 'cancelado'::text])))
);


ALTER TABLE public.waiting_list OWNER TO postgres;

--
-- Name: COLUMN waiting_list.appointment_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.waiting_list.appointment_id IS 'ID do agendamento vinculado na tabela appointments';


--
-- Name: whatsapp_reminders; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.whatsapp_reminders (
    id text NOT NULL,
    appointment_id text,
    patient_name text NOT NULL,
    patient_phone text NOT NULL,
    message_template text NOT NULL,
    language text DEFAULT 'es'::text NOT NULL,
    status text DEFAULT 'scheduled'::text NOT NULL,
    scheduled_for timestamp with time zone NOT NULL,
    sent_at timestamp with time zone,
    response_received text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT whatsapp_reminders_language_check CHECK ((language = ANY (ARRAY['es'::text, 'gn'::text, 'pt'::text, 'pt-BR'::text, 'pt-PT'::text, 'es-AR'::text, 'es-PY'::text, 'en'::text]))),
    CONSTRAINT whatsapp_reminders_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'sent'::text, 'delivered'::text, 'read'::text, 'confirmed'::text, 'cancelled'::text, 'rescheduled'::text])))
);


ALTER TABLE public.whatsapp_reminders OWNER TO postgres;

--
-- Name: messages; Type: TABLE; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE TABLE realtime.messages (
    topic text NOT NULL,
    extension text NOT NULL,
    payload jsonb,
    event text,
    private boolean DEFAULT false,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    inserted_at timestamp without time zone DEFAULT now() NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    binary_payload bytea
)
PARTITION BY RANGE (inserted_at);


ALTER TABLE realtime.messages OWNER TO supabase_realtime_admin;

